class Solution:
    def findValidSplit(self, nums: list[int]) -> int:
        def primes_of(x):
            ps, d = [], 2
            while d * d <= x:
                if x % d == 0:
                    ps.append(d)
                    while x % d == 0: x //= d
                d += 1
            if x > 1: ps.append(x)
            return ps
        n = len(nums)
        last = {}
        plists = [primes_of(x) for x in nums]
        for i, ps in enumerate(plists):
            for p in ps: last[p] = i
        mx = 0
        for i in range(n - 1):
            for p in plists[i]:
                mx = max(mx, last[p])
            if mx <= i: return i
        return -1

