class Solution {
public:
    int findValidSplit(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int,int> last;
        vector<vector<int>> plists(n);
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            for (int d = 2; d * d <= x; d++)
                if (x % d == 0) {
                    plists[i].push_back(d);
                    while (x % d == 0) x /= d;
                }
            if (x > 1) plists[i].push_back(x);
            for (int p : plists[i]) last[p] = i;
        }
        int mx = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int p : plists[i]) mx = max(mx, last[p]);
            if (mx <= i) return i;
        }
        return -1;
    }
};

