import java.util.*;
class Solution {
    public int findValidSplit(int[] nums) {
        int n = nums.length;
        Map<Integer,Integer> last = new HashMap<>();
        List<List<Integer>> plists = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            List<Integer> ps = new ArrayList<>();
            for (int d = 2; (long)d * d <= x; d++)
                if (x % d == 0) {
                    ps.add(d);
                    while (x % d == 0) x /= d;
                }
            if (x > 1) ps.add(x);
            plists.add(ps);
            for (int p : ps) last.put(p, i);
        }
        int mx = 0;
        for (int i = 0; i < n - 1; i++) {
            for (int p : plists.get(i)) mx = Math.max(mx, last.get(p));
            if (mx <= i) return i;
        }
        return -1;
    }
}

