        plists.push(ps);
        for (const p of ps) last.set(p, i);
    }
    let mx = 0;
    for (let i = 0; i < n - 1; i++) {
        for (const p of plists[i]) mx = Math.max(mx, last.get(p));
        if (mx <= i) return i;
